#include <sys/mman.h>
#include <sys/socket.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>

int main() {
    int sv[2];
    if (socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == -1) {
        perror("socketpair");
    }

    // mlock(NULL, 0x800000)
    // In C, NULL is 0.
    if (mlock((void*)0, 0x800000) == -1) {
        perror("mlock");
    }

    // munlockall()
    if (munlockall() == -1) {
        perror("munlockall");
    }

    // Check maps
    system("cat /proc/self/maps");

    return 0;
}

